await page.locator('#begin-btn').click();
let direction = 'd', previous = 19, prompt = false;
await page.keyboard.down(direction);
for (let i=0;i<22;i++) {
  await page.waitForTimeout(1000);
  const text = await page.locator('#objective-distance').textContent();
  const distance = Number(text.match(/\d+/)?.[0] ?? 100);
  prompt = await page.locator('#interact-prompt').evaluate(e => e.classList.contains('visible'));
  console.log('step', i + 1, 'distance', distance, 'prompt', prompt);
  if (prompt) break;
  if (direction === 'd' && distance > previous) {
    await page.keyboard.up('d'); direction = 'a'; await page.keyboard.down('a');
  } else if (direction === 'a' && distance < previous && i > 0) {
    await page.keyboard.up('a'); direction = 'd'; await page.keyboard.down('d');
  }
  previous = distance;
}
await page.keyboard.up(direction);
if (prompt) {
  await page.keyboard.press('e'); await page.waitForTimeout(100);
  console.log('shrine interaction panel', await page.locator('#shrine-panel').evaluate(e => !e.classList.contains('hidden')));
