  console.log('rest closes panel', await page.locator('#shrine-panel').evaluate(e => e.classList.contains('hidden')));
} else console.log('shrine not reached');
console.log('errors', errors);
await page.screenshot({path:'/tmp/opencode/cinzas-shrine-interaction.png'});
await browser.close();
EOF

