DISPLAY=:0 node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = await import('node:fs/promises').then(fs => fs.readFile('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8')).then(JSON.parse);
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:4173', { waitUntil: 'networkidle' });
await page.locator('#begin-btn').click();
await page.keyboard.press('j'); await page.waitForTimeout(100);
console.log('light attack stamina', await page.locator('#stamina-text').textContent());
await page.keyboard.down('f'); await page.waitForTimeout(1200); await page.keyboard.up('f');
console.log('continuous fire mana', await page.locator('#mana-text').textContent());
await page.keyboard.down('d');
for (let i=0;i<5;i++) {
  await page.waitForTimeout(4000);
  console.log('approach', i + 1, 'target visible', await page.locator('#target-ui').evaluate(e => e.classList.contains('visible')), 'distance', await page.locator('#objective-distance').textContent(), 'health', await page.locator('#health-text').textContent());
  if (await page.locator('#target-ui').evaluate(e => e.classList.contains('visible'))) break;
}
await page.keyboard.up('d');
if (await page.locator('#target-ui').evaluate(e => e.classList.contains('visible'))) {
  const before = await page.locator('#target-fill').evaluate(e => e.style.width);
  await page.keyboard.down('f'); await page.waitForTimeout(2500); await page.keyboard.up('f');
  const after = await page.locator('#target-fill').evaluate(e => e.style.width);
  console.log('fire target health', before, '=>', after, 'player hp', await page.locator('#health-text').textContent());
} else console.log('target not reached in test window');
await page.keyboard.press('Escape');
console.log('pause overlay', await page.locator('#pause-panel').evaluate(e => !e.classList.contains('hidden')));
await page.locator('#resume-btn').click();
console.log('resume', await page.locator('#overlay').evaluate(e => e.classList.contains('hidden-overlay')));
console.log('errors', errors);
await page.screenshot({path:'/tmp/opencode/cinzas-combat.png'});
await browser.close();
EOF

